/**
 * SafetyReportExporter - PDF export for safety check reports
 */
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import type { SafetyCheckResult } from '@/types';

interface ExportOptions {
  ingredients: string[];
  result: SafetyCheckResult;
  complianceRate: number;
}

export function exportSafetyReport(options: ExportOptions): void {
  const { ingredients, result, complianceRate } = options;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const pageW = doc.internal.pageSize.getWidth();
  const margin = 20;
  const contentW = pageW - margin * 2;
  let y = 15;

  const PRIMARY: [number, number, number] = [59, 130, 246];
  const DANGER: [number, number, number] = [220, 38, 38];
  const SUCCESS: [number, number, number] = [34, 197, 94];
  const GRAY: [number, number, number] = [100, 116, 139];
  const DARK: [number, number, number] = [15, 23, 42];

  doc.setFillColor(PRIMARY[0], PRIMARY[1], PRIMARY[2]);
  doc.rect(0, 0, pageW, 38, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(20);
  doc.setFont('helvetica', 'bold');
  doc.text('Safety Compliance Report', margin, 18);
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('RMFOOD Formula R&D Platform', margin, 27);
  doc.text(new Date().toLocaleString('zh-CN'), margin, 33);
  y = 48;

  doc.setTextColor(DARK[0], DARK[1], DARK[2]);
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('Overview', margin, y);
  y += 2;
  doc.setDrawColor(GRAY[0], GRAY[1], GRAY[2]);
  doc.line(margin, y, margin + 40, y);
  y += 8;

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(GRAY[0], GRAY[1], GRAY[2]);
  doc.text('Ingredients:', margin, y);
  y += 5;
  doc.setFontSize(10);
  doc.setTextColor(DARK[0], DARK[1], DARK[2]);
  const ingLines = doc.splitTextToSize(ingredients.join(', '), contentW);
  doc.text(ingLines, margin, y);
  y += ingLines.length * 5 + 6;

  const passed = (result as Partial<SafetyCheckResult>).passed ?? true;
  const badgeColor = passed ? SUCCESS : DANGER;
  doc.setFillColor(badgeColor[0], badgeColor[1], badgeColor[2]);
  doc.roundedRect(margin, y - 4, 22, 8, 2, 2, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(9);
  doc.setFont('helvetica', 'bold');
  doc.text(passed ? 'PASS' : 'FAIL', margin + 11, y + 1.5);
  doc.setFontSize(11);
  doc.setTextColor(badgeColor[0], badgeColor[1], badgeColor[2]);
  doc.text('Compliance: ' + complianceRate.toFixed(1) + '%', margin + 28, y + 1.5);
  y += 14;

  const warnings = (result as Partial<SafetyCheckResult>).warnings || [];
  const errors = result.errors || [];
  const details: Record<string, any> = (result as any).details || {};

  const dangerCount = warnings.filter((w: any) => ['danger','critical','contraindicated'].includes(w.level)).length;
  const warningCount = warnings.filter((w: any) => ['warning','caution'].includes(w.level)).length;

  if (dangerCount > 0 || warningCount > 0) {
    doc.setFontSize(9);
    doc.setTextColor(GRAY[0], GRAY[1], GRAY[2]);
    doc.text('Risks: ' + dangerCount + ' danger, ' + warningCount + ' warnings', margin, y);
    y += 6;
  }

  const allIssues = [
    ...warnings.map((w) => ({
      type: w.level === 'danger' ? 'DANGER' : 'WARNING',
      ingredient: w.ingredient || (w as any).name || '-',
      message: (w.message || (w as any).reason || String(w)).slice(0, 80),
    })),
    ...errors.map((e) => ({
      type: 'ERROR',
      ingredient: '-',
      message: (typeof e === 'string' ? e : (e as any).message || String(e)).slice(0, 80),
    })),
  ];

  if (allIssues.length > 0) {
    y += 4;
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(DARK[0], DARK[1], DARK[2]);
    doc.text('Issues', margin, y);
    y += 2;
    doc.line(margin, y, margin + 30, y);
    y += 8;

    autoTable(doc, {
      startY: y,
      margin: { left: margin, right: margin },
      columnStyles: {
        0: { cellWidth: 30, fontStyle: 'bold' },
        1: { cellWidth: 35 },
        2: { cellWidth: 'auto' },
      },
      head: [['Type', 'Ingredient', 'Detail']],
      headStyles: { fillColor: GRAY, textColor: 255, fontStyle: 'bold', fontSize: 9 },
      bodyStyles: { fontSize: 8.5, textColor: DARK },
      alternateRowStyles: { fillColor: [248, 250, 252] },
      styles: { cellPadding: 3, lineColor: [226, 232, 240] },
      body: allIssues.map((issue) => [issue.type, issue.ingredient, issue.message]),
    });
    y = (doc as { lastAutoTable?: { finalY?: number } }).lastAutoTable?.finalY ? (doc as any).lastAutoTable?.finalY + 10 : y + 10;
  }

  const checkKeys = Object.keys(details);
  if (checkKeys.length > 0) {
    y += 4;
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(DARK[0], DARK[1], DARK[2]);
    doc.text('Check Items', margin, y);
    y += 2;
    doc.line(margin, y, margin + 30, y);
    y += 8;

    const checkData = checkKeys.map((key) => {
      const val = details[key];
      const isPassed = val?.passed ?? true;
      return [key.replace(/_/g, ' '), isPassed ? 'Pass' : 'Fail', val?.message || ''];
    });

    autoTable(doc, {
      startY: y,
      margin: { left: margin, right: margin },
      columnStyles: {
        0: { cellWidth: 50, fontStyle: 'bold' },
        1: { cellWidth: 25 },
        2: { cellWidth: 'auto' },
      },
      head: [['Item', 'Result', 'Note']],
      headStyles: { fillColor: GRAY, textColor: 255, fontStyle: 'bold', fontSize: 9 },
      bodyStyles: { fontSize: 8.5, textColor: DARK },
      alternateRowStyles: { fillColor: [248, 250, 252] },
      styles: { cellPadding: 3, lineColor: [226, 232, 240] },
      body: checkData,
    });
  }

  const pageH = doc.internal.pageSize.getHeight();
  doc.setFillColor(248, 250, 252);
  doc.rect(0, pageH - 20, pageW, 20, 'F');
  doc.setFontSize(8);
  doc.setTextColor(GRAY[0], GRAY[1], GRAY[2]);
  doc.text('Generated by RMFOOD AI Assistant - For reference only', margin, pageH - 12);

  const dateStr = new Date().toISOString().slice(0, 10);
  doc.save('safety_report_' + ingredients.slice(0, 3).join('-') + '_' + dateStr + '.pdf');
}

/**
 * Agent 工作流 E2E 测试
 *
 * 测试范围：
 * - AgentWorkflowTab 渲染和交互
 * - Turn/Step 状态显示
 * - Token 计数器
 * - Compaction 触发
 * - 工作流模板切换
 * - Waterfall 事件可视化
 */

import { test, expect } from '@playwright/test';

const AGENT_WORKFLOW_URL = '/agent';

// ── 辅助函数 ────────────────────────────────────────────────

async function navigateToAgentWorkflow(page: any): Promise<void> {
  await page.goto(AGENT_WORKFLOW_URL);
  // 等待多智能体协作中心加载，进入 Chief 控制台（AgentWorkflowTab 迁移到 /agent）
  await page.waitForSelector('[data-testid="agent-nav-chief"]', { timeout: 10000 });
  await page.locator('[data-testid="agent-nav-chief"]').click();
  await page.waitForSelector('[data-testid="agent-input"]', { timeout: 10000 });
}

async function sendAgentMessage(page: any, message: string): Promise<void> {
  const textarea = page.locator('[data-testid="agent-input"]');
  await textarea.fill(message);
  await textarea.press('Enter');
}

async function waitForAgentResponse(page: any, timeout: number = 15000): Promise<void> {
  // 等待 running 状态消失
  await page.waitForSelector('.animate-spin', { state: 'hidden', timeout });
  // 等待新消息出现（使用 data-testid）
  await page.locator('[data-testid="assistant-message"]').last().waitFor({ state: 'visible', timeout });
}

// ── 测试套件 ────────────────────────────────────────────────

test.describe('Agent 工作流 E2E 测试', () => {
  test.beforeEach(async ({ page }) => {
    await navigateToAgentWorkflow(page);
  });

  test('应渲染 Agent Workflow Tab', async ({ page }) => {
    // 检查头部
    await expect(page.locator('text=AI 研发助手')).toBeVisible();
    await expect(page.locator('text=Agent v3.0')).toBeVisible();

    // 检查工作流模板按钮
    const templates = page.locator('.rounded-full.border');
    await expect(templates).toHaveCountGreaterThan(0);

    // 检查输入框
    const textarea = page.locator('textarea');
    await expect(textarea).toBeVisible();
    await expect(textarea).toHaveAttribute('placeholder', /描述你的研发需求/);
  });

  test('应显示快捷提示按钮', async ({ page }) => {
    const promptButtons = page.locator('button:text("帮我设计一款")');
    await expect(promptButtons).toBeVisible();
  });

  test('发送消息后应显示 Turn 状态', async ({ page }) => {
    // Mock API 响应
    await page.route('/api/v1/agent/**', route => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          success: true,
          data: {
            execution_id: 'test-exec-123',
            user_query: '测试消息',
            status: 'completed',
            total_latency_ms: 1500,
            steps: [
              { step_id: '1', tool: 'rag_search', status: 'success', latency_ms: 500 },
              { step_id: '2', tool: 'formula_generate', status: 'success', latency_ms: 800 },
              { step_id: '3', tool: 'compliance_check', status: 'success', latency_ms: 200 },
            ],
            final_response_preview: '这是一条测试回复',
          },
        }),
      });
    });

    await page.route('/api/v1/agent/workflow/*/execute', route => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          success: true,
          data: {
            execution_id: 'test-wf-123',
            workflow_type: 'formula_design',
            user_query: '测试消息',
            status: 'completed',
            total_latency_ms: 1500,
            stages: [
              { stage: 'RAG检索', success: true, latency_ms: 500 },
              { stage: '配方生成', success: true, latency_ms: 800 },
              { stage: '合规检查', success: true, latency_ms: 200 },
            ],
            final_response_preview: '配方设计方案已生成',
          },
        }),
      });
    });

    await sendAgentMessage(page, '帮我设计一款针对高血糖人群的饮品配方');
    await waitForAgentResponse(page);

    // 验证消息显示
    const messages = page.locator('[class*="flex items-start"]');
    await expect(messages).toHaveCountGreaterThan(1);
  });

  test('应显示 Token 计数器', async ({ page }) => {
    const tokenBadge = page.locator('[data-testid="token-indicator"]');
    await expect(tokenBadge).toBeVisible();
  });

  test('Token 指示器应显示进度条', async ({ page }) => {
    // 点击 Token 指示器展开详情
    const tokenBadge = page.locator('[data-testid="token-indicator"]');
    await tokenBadge.click();

    // 等待进度条显示
    await page.waitForSelector('[class*="h-1.5.rounded-full"]', { timeout: 3000 });
  });

  test('清空对话应清除所有消息', async ({ page }) => {
    const clearButton = page.locator('[title="清空对话"]');
    await expect(clearButton).toBeVisible();

    // 清空前应有空状态
    await expect(page.locator('text=开始新的对话')).toBeVisible();
  });

  test('应显示工作流节点可视化', async ({ page }) => {
    // 工作流节点应默认隐藏（未执行时）
    const workflowNode = page.locator('[class*="border-min-w-\\[80px\\]"]');
    // 当没有执行时，工作流节点面板不应显示
    const isVisible = await workflowNode.count();
    // 允许为空或不显示
    expect(isVisible >= 0).toBe(true);
  });

  test('选择快捷提示应填充输入框', async ({ page }) => {
    const promptButton = page.locator('button:text("查询黄芪的功效")').first();
    await expect(promptButton).toBeVisible();
    await promptButton.click();

    const textarea = page.locator('textarea');
    const value = await textarea.inputValue();
    expect(value).toContain('黄芪');
  });
});

test.describe('Agent 工作流 - 智能路由测试', () => {
  test.beforeEach(async ({ page }) => {
    await navigateToAgentWorkflow(page);
  });

  test('输入"配方"应路由到配方设计模式', async ({ page }) => {
    const textarea = page.locator('textarea');
    await textarea.fill('帮我设计一款配方');

    // 检查智能路由指示器
    const routerIndicator = page.locator('[class*="Brain"]');
    // 输入时可能显示路由建议
    await expect(routerIndicator).toBeVisible();
  });

  test('输入"合规检查"应路由到合规检查模式', async ({ page }) => {
    const textarea = page.locator('textarea');
    await textarea.fill('检查这个配方的合规性');

    const routerIndicator = page.locator('[class*="Brain"]');
    await expect(routerIndicator).toBeVisible();
  });
});

test.describe('Agent 工作流 - 错误处理测试', () => {
  test('API 失败时应显示错误消息', async ({ page }) => {
    // Mock 错误响应
    await page.route('/api/v1/agent/**', route => {
      route.fulfill({
        status: 500,
        contentType: 'application/json',
        body: JSON.stringify({ error: 'Internal Server Error' }),
      });
    });

    await page.route('/api/v1/agent/workflow/*/execute', route => {
      route.fulfill({
        status: 500,
        contentType: 'application/json',
        body: JSON.stringify({ error: 'Workflow execution failed' }),
      });
    });

    await sendAgentMessage(page, '测试错误处理');

    // 等待错误消息出现
    await page.waitForSelector('text=/执行失败|错误/i', { timeout: 10000 });
  });

  test('网络超时时应显示超时提示', async ({ page }) => {
    await page.route('/api/v1/agent/**', route => {
      route.abort('connectiontimedout');
    });

    await sendAgentMessage(page, '测试超时');

    // 等待错误消息
    await page.waitForSelector('text=/失败/i', { timeout: 15000 });
  });
});

test.describe('Agent 工作流 - 性能测试', () => {
  test('首次加载应小于 2 秒', async ({ page }) => {
    const startTime = Date.now();
    await navigateToAgentWorkflow(page);
    const loadTime = Date.now() - startTime;

    expect(loadTime).toBeLessThan(2000);
  });

  test('多次消息发送应保持流畅', async ({ page }) => {
    // Mock 快速响应
    await page.route('/api/v1/agent/**', route => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          success: true,
          data: {
            execution_id: `exec-${Date.now()}`,
            user_query: '',
            status: 'completed',
            total_latency_ms: 100,
            steps: [],
            final_response_preview: 'OK',
          },
        }),
      });
    });

    // 发送 5 条消息
    for (let i = 0; i < 5; i++) {
      const before = Date.now();
      await sendAgentMessage(page, `测试消息 ${i + 1}`);
      await waitForAgentResponse(page, 5000);
      const after = Date.now();

      // 每条消息处理应在 5 秒内完成
      expect(after - before).toBeLessThan(5000);
    }
  });
});

// ── 测试计数辅助 ────────────────────────────────────────────

expect.extend({
  toHaveCountGreaterThan(received: any, expected: number) {
    const actual = received.count();
    const pass = actual > expected;
    return {
      pass,
      message: () => `expected element count ${actual} to ${pass ? '>' : '<'}= ${expected}`,
    };
  },
});

import { useState, useCallback, useEffect } from 'react';
import { X, Copy, Loader2, CheckCircle } from 'lucide-react';
import { Modal } from '@/components/ui';

interface CloneOrgDialogProps {
  open: boolean;
  sourceOrg: { id: number; name: string; slug: string; plan: string } | null;
  onClone: (newName: string) => Promise<number>;
  onClose: () => void;
  onCloned?: (newId: number) => void;
}

export function CloneOrgDialog({ open, sourceOrg, onClone, onClose, onCloned }: CloneOrgDialogProps) {
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [cloned, setCloned] = useState(false);

  useEffect(() => {
    if (open) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setName(sourceOrg ? `${sourceOrg.name} (副本)` : '');
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setError(null);
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setCloned(false);
    }
  }, [open, sourceOrg]);

  const handleClone = useCallback(async () => {
    if (!name.trim()) {
      setError('副本名称不能为空');
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const newId = await onClone(name.trim());
      setCloned(true);
      setTimeout(() => {
        onClose();
        onCloned?.(newId);
      }, 1200);
    } catch (err: any) {
      setError(err?.response?.data?.detail || err?.message || '克隆失败，请重试');
    } finally {
      setLoading(false);
    }
  }, [name, onClone, onClose, onCloned]);

  return (
    <Modal open={open} onClose={onClose} title="克隆组织" size="sm">
      <div className="space-y-5">
        {sourceOrg && (
          <div className="flex items-center gap-[var(--space-apple-sm)] p-[var(--space-apple-md)] bg-[var(--bg-tertiary)] dark:bg-[var(--bg-secondary)]/30 rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] dark:border-neutral-800">
            <div className="w-10 h-10 bg-gradient-to-br from-[var(--color-secondary-surface)] to-[var(--color-accent-surface-deep)] rounded-[var(--radius-Apple-md)] flex items-center justify-center text-white font-bold text-lg">
              {sourceOrg.name.charAt(0)}
            </div>
            <div>
              <p className="font-medium text-[var(--text-primary)]">{sourceOrg.name}</p>
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">@{sourceOrg.slug} · {sourceOrg.plan === 'pro' ? '专业版' : sourceOrg.plan === 'enterprise' ? '企业版' : '免费版'}</p>
            </div>
            <Copy className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] ml-auto" />
          </div>
        )}

        <div>
          <label className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
            副本名称 <span className="text-[var(--color-error-text)]0">*</span>
          </label>
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="输入新组织名称..."
            className="w-full px-[var(--space-apple-sm)] py-2.5 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-secondary)] text-[var(--text-primary)] text-sm focus:outline-none focus:ring-2 focus:ring-[var(--color-secondary)]"
            autoFocus
            onKeyDown={(e) => e.key === 'Enter' && !loading && handleClone()}
          />
          <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">克隆将复制成员、团队和基础配置</p>
        </div>

        {error && (
          <div className="flex items-center gap-2 text-sm text-[var(--color-error-text)] dark:text-[var(--color-error-text)] bg-[var(--color-error-container)] rounded-[var(--radius-Apple-sm)] px-[var(--space-apple-sm)] py-2">
            <X className="w-4 h-4 shrink-0" />
            {error}
          </div>
        )}

        {cloned && (
          <div className="flex items-center gap-2 text-sm text-[var(--color-success-text)] dark:text-[var(--color-success-text)] bg-[var(--color-success-container)] rounded-[var(--radius-Apple-sm)] px-[var(--space-apple-sm)] py-2">
            <CheckCircle className="w-4 h-4 shrink-0" />
            克隆成功！即将跳转...
          </div>
        )}

        <div className="flex justify-end gap-[var(--space-apple-sm)] pt-2">
          <button onClick={onClose} disabled={loading} className="px-[var(--space-apple-md)] py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-sm)] transition-colors">
            取消
          </button>
          <button
            onClick={handleClone}
            disabled={loading || cloned || !name.trim()}
            className="px-[var(--space-apple-md)] py-2 text-sm bg-secondary-container text-secondary-main rounded-[var(--radius-Apple-sm)] hover:bg-secondary-container disabled:opacity-50 transition-colors flex items-center gap-2"
          >
            {loading && <Loader2 className="w-4 h-4 animate-spin" />}
            {cloned ? <><CheckCircle className="w-4 h-4" />完成</> : '开始克隆'}
          </button>
        </div>
      </div>
    </Modal>
  );
}

export default CloneOrgDialog;

import { ProfessionalBaseService } from './ProfessionalBaseService';
import type { ProfessionalServiceConfig } from '../../types/professional';

export interface LiteratureArticle {
  id: string;
  title: string;
  titleEn?: string;
  abstract: string;
  abstractEn?: string;
  authors: string[];
  affiliations?: string[];
  journal: string;
  journalAbbreviation?: string;
  year: number;
  volume?: string;
  issue?: string;
  pages?: string;
  doi?: string;
  pmid?: string;
  issn?: string;
  keywords: string[];
  publicationType: 'article' | 'review' | 'letter' | 'short' | 'other';
  language: 'zh' | 'en' | 'other';
  source: 'pubmed' | 'cnki' | 'wanfang' | 'vip' | 'scopus' | 'custom';
  citedCount?: number;
  references?: string[];
  meshTerms?: string[];
  publicationDate: string;
  openAccess: boolean;
  fullTextUrl?: string;
  pdfUrl?: string;
}

export interface LiteratureSearchParams {
  query: string;
  keywords?: string[];
  authors?: string[];
  journals?: string[];
  yearRange?: { min: number; max: number };
  sources?: ('pubmed' | 'cnki' | 'wanfang' | 'vip' | 'scopus')[];
  languages?: ('zh' | 'en')[];
  publicationTypes?: ('article' | 'review' | 'letter')[];
  openAccess?: boolean;
  page?: number;
  pageSize?: number;
  sortBy?: 'relevance' | 'date' | 'citations';
  sortOrder?: 'asc' | 'desc';
}

export interface LiteratureSearchResult {
  articles: LiteratureArticle[];
